export interface Post {
  id: number
  title: string
  content: string
  createdAt: Date
}

const posts: Post[] = [
  {
    id: 1,
    title: "First Post",
    content: "This is my first post!",
    createdAt: new Date("2025-01-01"),
  },
  {
    id: 2,
    title: "Hello World",
    content: "Welcome to the blog.",
    createdAt: new Date("2025-01-02"),
  },
]

let nextId = 3

export function addPost(title: string, content: string): Post {
  const post: Post = {
    id: nextId++,
    title,
    content,
    createdAt: new Date(),
  }
  posts.push(post)
  return post
}

export async function getPosts(): Promise<Post[]> {
  "use cache"
  cacheTag("posts")
  cacheLife("seconds")
  return posts
}

